enum Coin {
    PENNY(1), NICKEL(5), DIME(10), QUARTER(25);
    final int value;
    Coin(int v) { this.value = v; }
}

class ProductSlot {
    private final String slotCode;
    private final String productName;
    private final int price; // cents
    private int quantity;

    public boolean isAvailable() { return quantity > 0; }

    public void dispense() {
        if (quantity <= 0)
            throw new OutOfStockException(slotCode);
        quantity--;
    }

    public void restock(int qty) { this.quantity += qty; }
    // getters...
}

class CoinBank {
    private final Map<Coin, Integer> coins = new EnumMap<>(Coin.class);

    public CoinBank() {
        for (Coin c : Coin.values()) coins.put(c, 0);
    }

    public void addCoin(Coin c) {
        coins.merge(c, 1, Integer::sum);
    }

    // Greedy change-making: largest coins first
    // Returns coins to dispense, or throws if impossible
    public Map<Coin, Integer> makeChange(int amount) {
        Map<Coin, Integer> change = new EnumMap<>(Coin.class);
        // Sort denominations descending
        Coin[] sorted = {Coin.QUARTER, Coin.DIME, Coin.NICKEL, Coin.PENNY};

        for (Coin c : sorted) {
            int available = coins.getOrDefault(c, 0);
            int needed = amount / c.value;
            int use = Math.min(needed, available);
            if (use > 0) {
                change.put(c, use);
                amount -= use * c.value;
            }
        }

        if (amount > 0)
            throw new CannotMakeChangeException("Short by " + amount + " cents");

        // Commit: deduct from bank
        change.forEach((c, qty) -> coins.merge(c, -qty, Integer::sum));
        return change;
    }

    public void refill(Coin c, int qty) {
        coins.merge(c, qty, Integer::sum);
    }
}

interface VendingState {
    void insertCoin(Coin coin);
    void selectProduct(String slotCode);
    void dispense();
    Map<Coin, Integer> cancel();
}

class IdleState implements VendingState {
    private final VendingMachine machine;

    public IdleState(VendingMachine m) { this.machine = m; }

    @Override
    public void insertCoin(Coin coin) {
        machine.addToBalance(coin.value);
        machine.getCoinBank().addCoin(coin);
        machine.setState(new CoinInsertedState(machine));
    }

    @Override
    public void selectProduct(String code) {
        throw new InvalidStateException("Insert coins first");
    }

    @Override
    public void dispense() {
        throw new InvalidStateException("No transaction in progress");
    }

    @Override
    public Map<Coin, Integer> cancel() {
        return Map.of(); // nothing to return
    }
}

class CoinInsertedState implements VendingState {
    private final VendingMachine machine;

    public CoinInsertedState(VendingMachine m) { this.machine = m; }

    @Override
    public void insertCoin(Coin coin) {
        machine.addToBalance(coin.value);
        machine.getCoinBank().addCoin(coin);
        // Stay in COIN_INSERTED
    }

    @Override
    public void selectProduct(String slotCode) {
        ProductSlot slot = machine.getSlot(slotCode); // throws InvalidSlotException
        if (!slot.isAvailable())
            throw new OutOfStockException(slotCode);
        if (machine.getCurrentBalance() < slot.getPrice())
            throw new InsufficientBalanceException(
                "Need " + slot.getPrice() + ", have " + machine.getCurrentBalance());

        machine.setSelectedSlot(slot);
        machine.setState(new DispensingState(machine));
    }

    @Override
    public void dispense() {
        throw new InvalidStateException("Select a product first");
    }

    @Override
    public Map<Coin, Integer> cancel() {
        int refund = machine.getCurrentBalance();
        Map<Coin, Integer> change = machine.getCoinBank().makeChange(refund);
        machine.resetBalance();
        machine.setState(new IdleState(machine));
        return change;
    }
}

class DispensingState implements VendingState {
    private final VendingMachine machine;

    public DispensingState(VendingMachine m) { this.machine = m; }

    @Override
    public void insertCoin(Coin coin) {
        throw new InvalidStateException("Dispensing in progress");
    }

    @Override
    public void selectProduct(String code) {
        throw new InvalidStateException("Dispensing in progress");
    }

    @Override
    public void dispense() {
        ProductSlot slot = machine.getSelectedSlot();
        int changeAmount = machine.getCurrentBalance() - slot.getPrice();

        // Try to make change BEFORE dispensing (atomic check)
        Map<Coin, Integer> change;
        try {
            change = (changeAmount > 0)
                ? machine.getCoinBank().makeChange(changeAmount)
                : Map.of();
        } catch (CannotMakeChangeException e) {
            // Rollback: return all inserted coins, cancel transaction
            Map<Coin, Integer> refund = machine.getCoinBank()
                .makeChange(machine.getCurrentBalance());
            machine.resetBalance();
            machine.setSelectedSlot(null);
            machine.setState(new IdleState(machine));
            throw new CannotMakeChangeException(
                "Cannot make change. Transaction cancelled. Refund: " + refund);
        }

        // All good — dispense
        slot.dispense(); // qty--
        machine.resetBalance();
        machine.setSelectedSlot(null);
        machine.setState(new IdleState(machine));
        // change is returned to caller
    }

    @Override
    public Map<Coin, Integer> cancel() {
        throw new InvalidStateException("Cannot cancel during dispensing");
    }
}

class VendingMachine {
    private VendingState currentState;
    private final Map<String, ProductSlot> slots;
    private final CoinBank coinBank;
    private int currentBalance = 0; // cents
    private ProductSlot selectedSlot;

    public VendingMachine(Map<String, ProductSlot> slots) {
        this.slots = slots;
        this.coinBank = new CoinBank();
        this.currentState = new IdleState(this);
    }

    // ── Public API (delegates to state) ─────
    public void insertCoin(Coin coin)          { currentState.insertCoin(coin); }
    public void selectProduct(String slotCode) { currentState.selectProduct(slotCode); }
    public void dispense()                     { currentState.dispense(); }
    public Map<Coin, Integer> cancel()         { return currentState.cancel(); }

    // ── State management ────────────────────
    void setState(VendingState state)     { this.currentState = state; }
    void addToBalance(int cents)          { this.currentBalance += cents; }
    void resetBalance()                   { this.currentBalance = 0; }
    int getCurrentBalance()               { return currentBalance; }
    void setSelectedSlot(ProductSlot s)   { this.selectedSlot = s; }
    ProductSlot getSelectedSlot()         { return selectedSlot; }
    CoinBank getCoinBank()                { return coinBank; }

    ProductSlot getSlot(String code) {
        ProductSlot slot = slots.get(code);
        if (slot == null)
            throw new InvalidSlotException("Unknown slot: " + code);
        return slot;
    }

    // ── Admin ───────────────────────────────
    public void restock(String slotCode, int qty) {
        getSlot(slotCode).restock(qty);
    }

    public void refillCoins(Coin coin, int qty) {
        coinBank.refill(coin, qty);
    }
}
